"""Local frontend walkthrough; no real account, network service or storage. Requires both review servers."""
import subprocess,json,os,atexit
from pathlib import Path
B=os.environ.get('AGENT_BROWSER_BIN','/private/tmp/mirar-npm-cache/_npx/6de2aa2fded2970c/node_modules/agent-browser/bin/agent-browser-darwin-arm64')
ROOT=Path(__file__).resolve().parents[2]/'docs/experience/aperture-validation';(ROOT/'screenshots').mkdir(exist_ok=True,parents=True)
rows=[]
atexit.register(lambda:(ROOT/'results.json').write_text(json.dumps(rows,indent=2)+'\n'))
def run(*args):
 p=subprocess.run([B,'--session','mirar-aperture-build-qa','--pin-tab',*args],capture_output=True,text=True,check=True);return p.stdout.strip()
def js(s):return json.loads(run('eval',s))
def click(name):run('find','role','button','click','--name',name,'--exact');run('wait','450')
def open(url,text):
 run('open',url);run('wait','--text',text);run('wait','450')
def screenshot(name):
 run('screenshot',str(ROOT/'screenshots'/f'{name}.png'))
 v=js("({overflow:document.documentElement.scrollWidth>innerWidth,small:[...document.querySelectorAll('button,a,[role=button]')].filter(e=>e.getBoundingClientRect().height>0&&getComputedStyle(e).visibility!=='hidden').filter(e=>e.getBoundingClientRect().height<43.9).map(e=>({text:e.textContent,height:e.getBoundingClientRect().height})),storage:Object.keys(localStorage),remote:performance.getEntriesByType('resource').map(e=>e.name).filter(n=>n.startsWith('http')&&new URL(n).origin!==location.origin)})")
 rows.append({'screen':name,'geometry':v});assert not v['overflow'],name+' overflow';assert not v['small'],name+str(v['small']);assert not v['storage'];assert not v['remote']
def audit(name):
 v=json.loads(run('a11y','--json'))['data'];rows.append({'a11y':name,'counts':v['counts'],'violations':v['violations'],'incomplete':v['incomplete']});assert not v['violations'],str(v['violations'])
for w,h in [(320,568),(390,844),(768,1024),(1024,768),(1440,900)]:
 run('set','viewport',str(w),str(h))
 open('http://127.0.0.1:5177/','Look within.');screenshot(f'landing-{w}');audit(f'landing-{w}')
 click('Begin sample');screenshot(f'sample-{w}');click('I don\'t know');screenshot(f'sample-unknown-{w}');audit(f'sample-unknown-{w}')
 assert 'Nothing more is asked of you.' in js('document.body.textContent');assert 'Notice once, later today' not in js('document.body.textContent')
 for stage,label in [('entry','Step into Mirar.'),('intro','Start with what is here.'),('today','A moment for yourself.'),('mirror','A beginning, without a verdict.'),('privacy','A clear account of what stays.'),('me','The practice is yours.')]:
  open('http://127.0.0.1:5174/?experience='+stage,label);screenshot(f'{stage}-{w}');audit(f'{stage}-{w}')
# A genuine first-session runtime flow, not a handcrafted completion fixture.
run('set','viewport','390','844');open('http://127.0.0.1:5174/?experience=discover','Look within.');click('Begin your practice')
run('find','role','textbox','fill','--name','Your email','--exact','synthetic-review@example.test');click('Send my sign-in link');screenshot('entry-sent');click('Local review: continue to introduction');click('Meet today’s Inner Rep');click('Begin');screenshot('first-rep')
click("I don't know");screenshot('first-integration');audit('first-integration');assert 'Nothing more is asked of you.' in js('document.body.textContent')
click('Reload runtime view');screenshot('done-reloaded');assert 'I don’t know' in js('document.body.textContent');rows.append({'receiptReloadInMemory':True})
# Contract-driven returning paths generated by Claude's REAL runtime builder.
for scenario in ['compare','words','followup','timeframe','commitment_check','thread_check','lens','resolution','open_question']:
 open('http://127.0.0.1:5174/?experience=today&scenario='+scenario,'A moment for yourself.');click('Begin');screenshot(scenario);audit(scenario)
 if scenario=='timeframe':
  click('Reply to one message');click('Pick a date');screenshot('date-picker');audit('date-picker')
  js("(()=>{const e=document.querySelector('input[type=date]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,'2000-01-01');e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));})()")
  assert js("[...document.querySelectorAll('[role=button]')].find(e=>e.textContent==='Use this date').getAttribute('aria-disabled')")=='true'
 forReturn=js("document.body.textContent.includes('Back to Today')");assert forReturn
 click('Back to Today')
# Sparse model is consumed via runtime.mirror(), no fabricated personal reading.
open('http://127.0.0.1:5174/?experience=mirror&scenario=compare','What is here.');screenshot('mirror-returning');audit('mirror-returning');assert 'Historical interpretations are not available' in js('document.body.textContent')
# Production feedback renderer paths; explicit fictional insight fixture only in local review.
reasons=["The situation is right, but what it means isn't","It matters, but not as much as that sounds","Something important is missing","That was true, but it has changed","Something else","I'd rather not say"]
for reason in reasons:
 open('http://127.0.0.1:5174/?case=mirror','Work has come up');click('Partly');click("What's off?");screenshot('correction-'+str(reasons.index(reason)));click(reason)
 if reason=='Something else':
  assert 'Optional. Not saved in this version.' in js('document.body.textContent');run('find','role','textbox','fill','--name','Tell Mirar more (optional)','--exact','Synthetic local note');click('Continue');assert not js("document.body.textContent.includes('Synthetic local note')")
 assert 'Your correction is recorded.' in js('document.body.textContent');assert 'Work has come up 5 times' not in js('document.body.textContent')
for answer in ['Accurate','No','Not sure']:
 open('http://127.0.0.1:5174/?case=mirror','Work has come up');click(answer);screenshot('feedback-'+answer.replace(' ','-'));audit('feedback-'+answer)
open('http://127.0.0.1:5174/?case=mirror','Work has come up');click('Partly');click("What's off?");click('Skip');assert not js("document.body.textContent.includes(\"What's off?\")");rows.append({'correctionSkipEnds':True})
# Keyboard, live reduced-motion preference, error state and fictional study isolation.
open('http://127.0.0.1:5177/','Look within.');run('set','media','reduced-motion');assert js("matchMedia('(prefers-reduced-motion: reduce)').matches")
click('Begin sample');js("[...document.querySelectorAll('[role=button]')].find(e=>e.textContent===\"I don't know\").focus()");run('press','Enter');assert 'Not knowing' in js('document.body.textContent');screenshot('keyboard-reduced-motion');rows.append({'keyboardUnknown':True,'reducedMotion':True})
open('http://127.0.0.1:5174/?experience=entry&error=1','Step into Mirar.');screenshot('entry-error');audit('entry-error')
open('http://127.0.0.1:5177/','Look within.');click('See a fictional study');screenshot('fictional-study');assert not js("[...document.querySelectorAll('[role=button],button')].some(e=>['Accurate','Partly','No','Not sure'].includes(e.textContent))")
assert js("[...document.querySelectorAll('nav[aria-label=Legal] a')].map(a=>a.href)")==['https://mirar.life/privacy','https://mirar.life/terms','https://mirar.life/cookies']
# Unconfigured CTA explicitly reports pending config instead of navigating to an invented path.
js("[...document.querySelectorAll('[role=button]')].find(e=>e.textContent==='Enter Mirar').click()");assert 'awaiting route confirmation' in js('document.body.textContent');rows.append({'legalDestinationsPreserved':True,'unconfiguredCtaGated':True})
rows.append({'browserErrors':run('errors')});assert not run('errors');print('Aperture walkthrough complete:',len(rows),'records')
